"use client";

import { useState } from "react";
import { 
  Wallet, ArrowUpRight, ArrowDownLeft, 
  Filter, Download, Plus, Search, 
  TrendingUp, PieChart, DollarSign, Calendar
} from "lucide-react";

// DATA DUMMY TRANSAKSI
const initialTransactions = [
  { id: 1, title: "Dana Sponsorship Telkomsel", category: "Sponsorship", date: "2026-01-02", type: "income", amount: 2500000, pic: "Raka (Ketua)" },
  { id: 2, title: "Belanja ATK Rapat Pleno", category: "Operasional", date: "2026-01-03", type: "expense", amount: 150000, pic: "Siti (Sekretaris)" },
  { id: 3, title: "Iuran Kas Kelas X RPL 1", category: "Kas Wajib", date: "2026-01-04", type: "income", amount: 300000, pic: "Bendahara 1" },
  { id: 4, title: "Konsumsi Tamu Pemateri", category: "Konsumsi", date: "2026-01-05", type: "expense", amount: 450000, pic: "Seksi Acara" },
  { id: 5, title: "Cetak Banner Event", category: "Perlengkapan", date: "2026-01-05", type: "expense", amount: 120000, pic: "Seksi Pubdok" },
];

export default function KasPage() {
  const [transactions, setTransactions] = useState(initialTransactions);
  const [filterType, setFilterType] = useState('all'); // all, income, expense

  // HITUNG SALDO OTOMATIS
  const totalIncome = transactions
    .filter(t => t.type === 'income')
    .reduce((acc, curr) => acc + curr.amount, 0);

  const totalExpense = transactions
    .filter(t => t.type === 'expense')
    .reduce((acc, curr) => acc + curr.amount, 0);

  const currentBalance = totalIncome - totalExpense;

  // FORMAT RUPIAH
  const formatRupiah = (number: number) => {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0,
    }).format(number);
  };

  // FILTER LOGIC
  const filteredData = filterType === 'all' 
    ? transactions 
    : transactions.filter(t => t.type === filterType);

  return (
    <div className="h-[calc(100vh-6rem)] flex flex-col xl:flex-row gap-6 font-sans">
      
      {/* === LEFT PANEL: DASHBOARD & STATS === */}
      <div className="w-full xl:w-[400px] flex flex-col gap-6 shrink-0 h-full overflow-y-auto custom-scrollbar pr-1">
         
         {/* 1. MAIN CARD (Digital Wallet Style) */}
         <div className="bg-gradient-to-br from-slate-900 via-[#0f172a] to-slate-800 p-6 rounded-2xl text-white shadow-2xl relative overflow-hidden group border border-slate-700">
            {/* Background Accents */}
            <div className="absolute top-0 right-0 w-40 h-40 bg-blue-500/20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
            <div className="absolute bottom-0 left-0 w-32 h-32 bg-purple-500/20 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2"></div>
            
            <div className="relative z-10">
               <div className="flex justify-between items-start mb-8">
                  <div className="p-2 bg-white/10 backdrop-blur-md rounded-lg border border-white/10">
                     <Wallet size={24} className="text-blue-400" />
                  </div>
                  <span className="text-[10px] font-bold uppercase tracking-widest bg-white/10 px-2 py-1 rounded text-slate-300">OSKA Finance</span>
               </div>
               
               <p className="text-slate-400 text-xs font-medium mb-1">Total Saldo Aktif</p>
               <h1 className="text-4xl font-black tracking-tight mb-6">{formatRupiah(currentBalance)}</h1>
               
               <div className="grid grid-cols-2 gap-4">
                  <div className="bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-colors">
                     <div className="flex items-center gap-2 mb-1">
                        <div className="p-1 bg-green-500/20 rounded text-green-400"><ArrowUpRight size={12}/></div>
                        <span className="text-[10px] text-slate-400 font-bold uppercase">Pemasukan</span>
                     </div>
                     <p className="text-sm font-bold text-green-400">{formatRupiah(totalIncome)}</p>
                  </div>
                  <div className="bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-colors">
                     <div className="flex items-center gap-2 mb-1">
                        <div className="p-1 bg-red-500/20 rounded text-red-400"><ArrowDownLeft size={12}/></div>
                        <span className="text-[10px] text-slate-400 font-bold uppercase">Pengeluaran</span>
                     </div>
                     <p className="text-sm font-bold text-red-400">{formatRupiah(totalExpense)}</p>
                  </div>
               </div>
            </div>
         </div>

         {/* 2. QUICK ACTIONS */}
         <div className="grid grid-cols-2 gap-4">
            <button className="p-4 bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow-lg shadow-blue-600/20 flex flex-col items-center justify-center gap-2 transition-all active:scale-95 group">
               <div className="p-2 bg-white/20 rounded-full group-hover:rotate-90 transition-transform"><Plus size={20}/></div>
               <span className="text-xs font-bold">Catat Transaksi</span>
            </button>
            <button className="p-4 bg-white dark:bg-[#0f172a] border border-slate-200 dark:border-white/10 text-slate-700 dark:text-slate-300 rounded-xl shadow-sm hover:shadow-md flex flex-col items-center justify-center gap-2 transition-all active:scale-95">
               <div className="p-2 bg-slate-100 dark:bg-white/10 rounded-full"><Download size={20}/></div>
               <span className="text-xs font-bold">Download Laporan</span>
            </button>
         </div>

         {/* 3. MINI STATS */}
         <div className="bg-white dark:bg-[#0f172a] p-5 rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm">
            <h3 className="text-xs font-black text-slate-800 dark:text-white uppercase tracking-wide mb-4 flex items-center gap-2">
               <TrendingUp size={16} className="text-blue-500"/> Financial Health
            </h3>
            
            {/* Progress Bar */}
            <div className="space-y-4">
               <div>
                  <div className="flex justify-between text-[10px] font-bold mb-1">
                     <span className="text-slate-500">Budget Terpakai</span>
                     <span className="text-slate-800 dark:text-white">{Math.round((totalExpense / totalIncome) * 100)}%</span>
                  </div>
                  <div className="h-2 w-full bg-slate-100 dark:bg-white/10 rounded-full overflow-hidden">
                     <div 
                        className="h-full bg-gradient-to-r from-blue-500 to-purple-500 rounded-full" 
                        style={{ width: `${(totalExpense / totalIncome) * 100}%` }}
                     ></div>
                  </div>
               </div>
               <p className="text-[10px] text-slate-400 leading-relaxed">
                  Kondisi keuangan <span className="text-green-500 font-bold">Sehat</span>. Pengeluaran masih di bawah 50% dari total pemasukan.
               </p>
            </div>
         </div>

      </div>

      {/* === RIGHT PANEL: TRANSACTION HISTORY === */}
      <div className="flex-1 bg-white dark:bg-[#0f172a] rounded-2xl border border-slate-200 dark:border-white/5 shadow-sm flex flex-col overflow-hidden">
         
         {/* Toolbar */}
         <div className="p-5 border-b border-slate-100 dark:border-white/5 flex justify-between items-center bg-slate-50/50 dark:bg-white/5">
            <div>
               <h2 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-wide">Riwayat Transaksi</h2>
               <p className="text-[10px] text-slate-500">Update terakhir: Baru saja</p>
            </div>
            
            <div className="flex gap-2">
               {/* Filter Buttons */}
               <div className="flex bg-white dark:bg-[#1e293b] rounded-lg border border-slate-200 dark:border-white/10 p-1">
                  <button onClick={() => setFilterType('all')} className={`px-3 py-1.5 rounded-md text-[10px] font-bold transition-all ${filterType === 'all' ? 'bg-slate-100 dark:bg-white/20 text-slate-800 dark:text-white shadow-sm' : 'text-slate-500 hover:text-slate-800'}`}>Semua</button>
                  <button onClick={() => setFilterType('income')} className={`px-3 py-1.5 rounded-md text-[10px] font-bold transition-all ${filterType === 'income' ? 'bg-green-100 text-green-700 shadow-sm' : 'text-slate-500 hover:text-green-600'}`}>Masuk</button>
                  <button onClick={() => setFilterType('expense')} className={`px-3 py-1.5 rounded-md text-[10px] font-bold transition-all ${filterType === 'expense' ? 'bg-red-100 text-red-700 shadow-sm' : 'text-slate-500 hover:text-red-600'}`}>Keluar</button>
               </div>
               
               <div className="relative">
                  <input type="text" placeholder="Cari..." className="pl-8 pr-3 py-2 bg-white dark:bg-[#1e293b] border border-slate-200 dark:border-white/10 rounded-lg text-xs outline-none focus:ring-2 focus:ring-blue-500 w-40" />
                  <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
               </div>
            </div>
         </div>

         {/* Table List */}
         <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
            <table className="w-full text-left border-collapse">
               <thead className="bg-slate-50 dark:bg-white/5 sticky top-0 z-10">
                  <tr>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider rounded-l-xl">Transaksi</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider">Kategori</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider">Tanggal</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider">PIC</th>
                     <th className="p-4 text-[10px] font-black text-slate-400 uppercase tracking-wider text-right rounded-r-xl">Jumlah</th>
                  </tr>
               </thead>
               <tbody className="text-xs">
                  {filteredData.map((t) => (
                     <tr key={t.id} className="border-b border-slate-50 dark:border-white/5 hover:bg-slate-50 dark:hover:bg-white/5 transition-colors group">
                        <td className="p-4">
                           <div className="flex items-center gap-3">
                              <div className={`p-2 rounded-full ${t.type === 'income' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                                 {t.type === 'income' ? <ArrowUpRight size={16}/> : <ArrowDownLeft size={16}/>}
                              </div>
                              <span className="font-bold text-slate-700 dark:text-slate-200">{t.title}</span>
                           </div>
                        </td>
                        <td className="p-4">
                           <span className="px-2 py-1 rounded-md bg-slate-100 dark:bg-white/10 text-[10px] font-bold text-slate-500">{t.category}</span>
                        </td>
                        <td className="p-4 text-slate-500 font-medium">
                           <div className="flex items-center gap-1.5"><Calendar size={12}/> {t.date}</div>
                        </td>
                        <td className="p-4 text-slate-500 font-medium">{t.pic}</td>
                        <td className={`p-4 text-right font-black ${t.type === 'income' ? 'text-green-600' : 'text-red-600'}`}>
                           {t.type === 'income' ? '+' : '-'} {formatRupiah(t.amount)}
                        </td>
                     </tr>
                  ))}
               </tbody>
            </table>
            
            {filteredData.length === 0 && (
               <div className="flex flex-col items-center justify-center py-20 text-slate-400 opacity-50">
                  <DollarSign size={48} className="mb-2"/>
                  <p className="text-sm font-bold">Tidak ada transaksi ditemukan</p>
               </div>
            )}
         </div>

      </div>
    </div>
  );
}